"""Reconcile the evaluated Gen5 mass, interference and mission records."""
import argparse
from pathlib import Path
import json,hashlib,sys,csv
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'analysis'));import mass_properties as m
parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
def emit(path,text):
 if args.check:
  if not path.is_file() or path.read_text()!=text:raise SystemExit('Stale evidence record: '+str(path.relative_to(R)))
 else:path.write_text(text)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
load=lambda p:json.loads((R/p).read_text())
# Each nonzero geometric pair receives an explicit conservative study disposition.
census=load('cad/GEN5_FULL_INTERFERENCE_AUDIT_2026_10_12.json'); pairs=[]
for model,d in census['models'].items():
 for p in d['intersections']:
  names={p['part_a'],p['part_b']}
  if names=={'Track','Sled'}:kind='CONFIRMED_MOVING_GEOMETRY_CONFLICT';why='Roller/body proxy occupies uncut longeron volume.';correction='New rail corridor, bearing gaps and deflected sweep; rerun dynamics/mass/brake.'
  elif names=={'Sled','Stator'}:kind='CONFIRMED_MOVING_GEOMETRY_CONFLICT';why='Backstop crosses the active stator proxy.';correction='Redesign backstop/contact and coil keep-out in a separately numbered revision.'
  elif 'Track' in names and any(n.startswith('Magazine') for n in names):kind='CONFIRMED_PACKAGING_FAILURE';why='Specified track and side cassettes require 537 mm in 526 mm clear width.';correction='Separate wider or rearranged configuration, with complete new budgets.'
  elif 'Interface_ESPA' in names:kind='UNRESOLVED_ADAPTER_PROXY_INTERSECTION';why='Adapter/hub/gusset proxy occupies another part; no joint drawing proves intended contact.';correction='Replace with parametric adapter, explicit datum, cutouts and verified load path.'
  else:kind='UNRESOLVED_PAYLOAD_ACCOMMODATION_INTERSECTION';why='Full payload proxy penetrates cassette wall/septum/rail representation; no approved contact geometry.';correction='Define keep-outs, permitted rails, pitch and tolerance; verify every stored envelope.'
  pairs.append(dict(configuration=model,**p,classification=kind,cause=why,correction=correction,engineering_status='NOT_REPAIRED',study_disposition='RETAIN_FAILED_OR_UNRESOLVED_CONFIGURATION; NO CLEARANCE OR INTENDED CONTACT CLAIM'))
assert len(pairs)==22
out={'census_sha256':sha(R/'cad/GEN5_FULL_INTERFERENCE_AUDIT_2026_10_12.json'),'classification_rule':'No nonzero solid penetration is accepted as contact without a drawing or physical interface definition. Classification closes interpretation only, never a geometry repair.','pairs':pairs}
emit(R/'cad/GEN5_INTERFERENCE_DISPOSITION.json',json.dumps(out,indent=2)+'\n')
lines=['# Gen5 and widened R1 interference disposition','','The evaluated geometry is preserved. Every nonzero pair in the exact-solid census is classified below. None is accepted as a clearance pass or as proven intentional contact. No geometry repair is made by this disposition. The separate Gen6 R2/R0 models cannot clear Gen5.','','| Configuration | Pair | Intersection mm³ | Classification | Correction |','|:--|:--|--:|:--|:--|']
for p in pairs:lines.append(f"| {p['configuration']} | {p['part_a']} / {p['part_b']} | {p['intersection_mm3']:.3f} | {p['classification'].replace('_',' ').lower()} | {p['correction']} |")
lines+=['','Source: [exact pair census](GEN5_FULL_INTERFERENCE_AUDIT_2026_10_12.json), [classification JSON](GEN5_INTERFERENCE_DISPOSITION.json), [source builder](build_gen5.py). Finite overlap alone cannot determine a physical contact law, allowable strain or provider acceptance. All corrections require a new geometry revision and dependent model verification.']
emit(R/'cad/GEN5_INTERFERENCE_DISPOSITION.md','\n'.join(lines)+'\n')
# Exact historical mass rollup, explicit mapping and omitted/unresolved properties.
dt,cg,sled=m.build();rows=[]
for i,(name,mass,x) in enumerate(m.parts,1):
 if name.startswith('Track'):cad='Track';basis='parametric hollow-section estimate; 1.55 m mass length versus 1.8 m CAD'
 elif name.startswith('Stator'):cad='Stator';basis='fill-factor material estimate; not solid proxy density'
 elif name.startswith('Sled'):cad='Sled';basis='parametric plus historical Gen3 solid-volume reconciliation'
 elif 'Cassette' in name or 'Followers' in name:cad='Magazine_P / Magazine_S';basis='shell/fill or lump estimate; feeder not modeled'
 elif 'brake' in name.lower():cad='Brake';basis='primitive/lump estimate; no selected brake'
 elif 'ESPA' in name:cad='Interface_ESPA';basis='assumed lump; provider mount not selected'
 elif any(s in name for s in ['Enclosure','Panels','Radiator','Fasteners','Equipment']):cad='Enclosure or omitted detail';basis='skin/fill/lump estimate; allocation overlap must be resolved in any redesign'
 else:cad='not individually represented';basis='assumed lump; no selected component'
 rows.append({'item':i,'name':name,'mass_kg':mass,'cg_x_m':x,'first_moment_kg_m':mass*x,'CAD_reference':cad,'basis':basis})
mass={'source_sha256':sha(R/'analysis/mass_properties.py'),'cad_parameters_sha256':sha(R/'cad/parameters.json'),'historical_dry_kg':dt,'historical_loaded_kg':dt+48,'modeled_axial_cg_m':cg,'first_moment_kg_m':sum(x['first_moment_kg_m'] for x in rows),'kg_per_3U':dt/12,'full_tensor_kg_m2':None,'rows':rows,'unresolved':['No installed BOM or vendor-checked component masses','x-only lump centers are not measured assembly CG; lateral/vertical CG and full inertia unavailable','Historical Gen3 sled volume is not a complete Gen5 material extraction','CAD solid material proxies cannot replace shell/fill mass estimates','Thermal/radiator, panel/enclosure and bracket allocations may overlap; no quantified credit taken','Harness routing, actual feeder/locks, actuator, winding ends and provider adapter lack installed detail','A new geometry or component selection requires a new mass/CG/inertia revision']}
emit(R/'analysis/results/gen5_mass_ledger.json',json.dumps(mass,indent=2)+'\n')
lines=['# Evaluated Gen5 mass and interface ledger','','**Historical model reconciliation, not a weighed or installation-ready assembly.** The 23 model lines total %.6f kg dry, %.6f kg loaded, and %.6f kg per carried 3U. The x-only model CG is %.6f m from its assumed breech datum. The rounded publications remain 126.6 kg, 174.6 kg, 10.55 kg/3U and 0.46 m. No physical tensor is inferred from missing three-dimensional placements.'%(dt,dt+48,dt/12,cg),'','| # | Model line | kg | CG x m | CAD representation | Evidence basis |','|--:|:--|--:|--:|:--|:--|']
for p in rows:lines.append(f"| {p['item']} | {p['name']} | {p['mass_kg']:.6f} | {p['cg_x_m']:.3f} | {p['CAD_reference']} | {p['basis']} |")
lines+=['','## Bounds and omissions','']+['- '+s for s in mass['unresolved']]+['','The quoted ±15%% model spread is an illustrative assumption, not a confidence interval. Even its low end is %.3f kg, or %.3f kg/3U; it still exceeds the 72 kg twelve-canister class assumption. This does not establish a fair current-product comparison: the 6 kg/3U benchmark is a historical class input, not a vendor-installed quote.'%(dt*.85,dt*.85/12),'','## Interface boundary','','Gen5 uses twelve 4 kg, 340.5 × 100 × 100 mm geometric proxies, not a selected spacecraft ICD. Its adapter is an intersecting ring/hub representation, not an approved ESPA interface. The separately versioned Gen6 study uses two 1U and two 3U at 1.33/4 kg nominal. CDS Rev. 14.1 gives class study ceilings of 2/6 kg; NRCSD Rev. - has different mission-specific limits. The [public reference audit](GEN6_GO1_PUBLIC_REFERENCE_AUDIT.md) identifies SwissCube and MinXSS as form-factor precedents. Neither is the selected payload.','','The generic maneuvering OTV deck, 500 km SSO and parametric adapter do not supply a real bolt pattern, allowable load, thermal, vacuum, EMC, shock or magnetic limit. The 5/10/25 g acceleration cases are provisional sensitivity inputs. Actual provider/payload documents govern compatibility.','','[Machine-readable ledger](../analysis/results/gen5_mass_ledger.json) · [Geometric failure disposition](../cad/GEN5_INTERFERENCE_DISPOSITION.md).']
emit(R/'docs/GEN5_MASS_AND_INTERFACE_LEDGER.md','\n'.join(lines)+'\n')
# Numerical uncertainty, fault paths and acceptance are grouped by evidence type.
accept=[('EM force','P118/P121 ideal work 1041.743 J; P119 2D 1081.6 J','P121/P118 share geometry, remanence and ideal phase; agreement is not model-form uncertainty','HISTORICAL SPEED CHALLENGED','Actual winding, drive, source, friction and force tests'),('Geometry','17 Gen5 and 5 widened-R1 intersections','Exact saved-solid census only; no tolerance/deflection or continuous motion proof','FAIL / UNRESOLVED','New geometry and re-analysis'),('Mass','126.561588 kg; 10.546799 kg/3U','Primitive/fill/lump model; ±15% is assumed, not statistical','FAIL HISTORICAL MASS SCREEN','Sourceable installed BOM and measured mass properties'),('Immediate orbit','28.800775 km for imposed inertial 16.029 m/s','0.02 m numerical band; no host or atmosphere in P115','PASS TWO-BODY IDENTITY ONLY','Finite host, real release state and mission control'),('Lifetime','P134 independent integration of shared static density','Numerical refinement below 0.5%; environmental/model-form error unbounded','CONDITIONAL MODEL OUTPUT','Time-varying atmosphere and current independent propagator'),('Mission','P123 12-shot matched reference','Finite optimizer search and 64 prefix corners; no global proof','NO SAMPLED OPTION COMPLETES','Named mission/host, feasible optimization and full resources'),('Release/contact','A34 zero-rate inference withdrawn','No measured compliance, preload or friction law','UNVERIFIED','Contact model and instrumented release'),('Structure/thermal/fields','Historical isolated cases only','No same-revision assembly/load/mesh qualification closure','UNVERIFIED','Updated FE, thermal, exposure and payload interface'),('Gen6 feeder','R2/R0 nominal states and sampled paths','No continuous tolerance/load/fault proof; ordinal scores not probabilities','UNSELECTED','Locks, docking, containment and same-boundary trade')]
lines=['# Gen5 uncertainty, acceptance and fault interpretation','','A software gate passing means that its stated calculation is consistent. It does not make a failed mechanical or mission criterion pass. Statistical confidence is not assigned to deterministic sensitivity cases or unmeasured reliability.','','| Area | Current evidence | Uncertainty boundary | Disposition | Remaining validation |','|:--|:--|:--|:--|:--|']
for p in accept:lines.append('| '+' | '.join(p)+' |')
lines+=['','## Fault tree and safe-state requirements','','Top event: unintended release, loose payload or loss of the remaining manifest. Credible branches are: stored-cell restraint failure; wrong-cell or multiple-cell opening; partial transfer with loss of power; unproved shared-path clearance; inconsistent position/lock sensors; premature propulsion command; failed carrier arrest; and loss of host pointing/recovery. These branches share power, control, rail and host resources, so their probabilities cannot be multiplied as independent events.','','| Fault path | Required inhibit/containment | Evidence status |','|:--|:--|:--|','| Stuck cell | Keep that payload independently locked; others proceed only after safe-path proof | Requirement; hardware proof absent |','| Power loss during transfer | Positive mechanical capture throughout transfer; supervised recovery | Critical open mechanism requirement |','| Gate/position sensor disagreement | Inhibit shot and cell opening; safe retained state | Logic requirement; implementation unverified |','| Unclear shared path or pusher not withdrawn | Inhibit propulsion and further feed | Nominal CAD states do not prove fault containment |','| Brake/reset or host recovery fault | Retain/contain carrier, halt sequence, supervise recovery | No demonstrated full shot/reset cycle |','','No numerical failure rate, P-POD-equivalent reliability, redundancy credit or safety certification follows from this fault tree. The separate [Gen6 cycle and faults](../cad/gen6_feeder/cycle_and_faults.md) defines transition guards; it remains a requirements record.']
emit(R/'docs/GEN5_UNCERTAINTY_AND_ACCEPTANCE.md','\n'.join(lines)+'\n')
life=load('analysis/results/gen5_lifetime_crosscheck.json');mission=load('analysis/results/matched_mission_reference.json')
lines=['# Gen5 orbit, lifetime and matched-mission disposition','','The 450 km Gen5 study and 500 km mixed-size Gen6 scenario are different configurations. Release speed relative to the host is not generally the payload inertial increment. A 4 kg payload separating at 16.029 m/s from a retained 300 kg host gains 15.818092 m/s and recoils the host by 0.210908 m/s. P115 instead imposes a 16.029 m/s inertial input; its 28.800775 km axis rise is an input-state geometry check.','','## Shared-atmosphere lifetime cross-check','','A separate DOP853 orbit-averaged energy/eccentricity integration uses midpoint anomaly quadrature and the declared static exponential density table. It imports no historical lifetime routine. Stopping at 120 km perigee gives:','','| Imposed inertial increment m/s | Base lifetime yr | Boosted lifetime yr | Ratio |','|--:|--:|--:|--:|']
for p in life['runs'][3:]:lines.append(f"| {p['speed_input_m_s']:.6f} | {p['base_lifetime_years']:.6f} | {p['lifetime_years']:.6f} | {p['lifetime_ratio']:.6f} |")
lines+=['',f"Refining from 360 to 720 anomaly nodes and rtol 1e-7 to 1e-9 changes a ratio by at most {100*life['max_ratio_refinement_fraction']:.6f}%, below the declared 0.5% numerical screen. These numbers reproduce the historical 1.60 and spring 1.082 ratios under a shared static atmosphere; they do not validate the atmosphere, physical release or lifetime in space. Uniform density/BC scaling is not a test of solar invariance. The 12.448 m/s row is an imposed inertial value for sensitivity, not the finite-host delivered state or a motor rating.",'','## Matched reference outcomes','','All options carry twelve 4 kg payloads, a 300 kg base host, 10 kg fuel, 2 kg reserve and 220 s host Isp. The common single-event target is +16.029 m/s inertial prograde. The 72 kg spring set and 126.562 kg Gen5 device are study assumptions.','','| Option | Device kg | Host preburn m/s | Event fuel kg | Accepted campaign prefix | Passing prefix corners |','|:--|--:|--:|--:|--:|--:|']
for a,b in zip(mission['single_event'],mission['finite_burn_campaign']):lines.append(f"| {a['option']} | {a['installed_device_kg']:.3f} | {a['host_preburn_m_s']:.6f} | {a['ideal_propellant_kg']:.6f} | {b['completed_deliveries']}/12 | {b['passing_prefix_corners']}/{b['uncertainty_corners_run']} |")
lines+=['','The single-event ideal solutions reach the same state by combining release with a host burn. Gen5 saves event fuel at an installed device penalty of 54.562 kg in this class comparison. A complete twelve-shot sampled solution is absent for every option. The optimizer stopping at a missing accepted seed is not proof of global infeasibility; prefix corner passes are not campaign success probabilities. Finite thrust, host maneuver/service restrictions and acceptance tolerances apply only as declared in [the full comparison](MATCHED_MISSION_REFERENCE.md).','','No matched onboard-propulsion, drag or quoted OTV service model is available. Those alternatives remain unevaluated, rather than being assigned losing scores. No customer, provider, continuous collision-clearance, disposal or economic advantage is established.','','[P134 inputs and result](../analysis/results/gen5_lifetime_crosscheck.json) · [P123 matched case](../analysis/results/matched_mission_reference.json) · [A15 corrected orbital screen](../validation/A15_poem_campaign.md).']
emit(R/'docs/GEN5_ORBIT_AND_MISSION_DISPOSITION.md','\n'.join(lines)+'\n')
print('PASS: 22 pair dispositions, 23-line exact historical mass ledger, uncertainty/fault matrix and mission/lifetime disposition.')
